select energy_manager.load_cards($cards$[
{"id":"p4-047","paper":4,"topic":"Compressed air","kind":"problem","front":"A 2-cylinder, single-acting reciprocating compressor (bore 250 mm, stroke 200 mm, 750 rpm) is tested by pump-up. Receiver 8 m³ + piping 0.4 m³ is filled from 1.0 to 8.0 kg/cm² (abs) in 4.5 min. Atmospheric pressure is 1.0 kg/cm² (abs). Intake air is at 30 °C and receiver air at 42 °C. Loaded input power is 75 kW. Find FAD, isothermal power, isothermal efficiency and volumetric efficiency.","back":"FAD ≈ 12.57 m³/min (≈ 444 cfm); isothermal power ≈ 42.7 kW; isothermal η ≈ 57%; volumetric η ≈ 85%","explain":"The temperature correction (303/315) lowers FAD by about 4%. Isothermal efficiency is taken here on measured electrical input, as in the BEE guidebook. On shaft power it would be higher.","steps":[{"prompt":"Free air delivery","answer":"(8 − 1)/1 × 8.4/4.5 × 303/315 = 12.57 m³/min","explain":"Pump-up formula with temperature correction."},{"prompt":"Isothermal power","answer":"1 × (12.57×60) × ln(8)/36.7 = 42.7 kW","explain":"P1 Q1 ln r / 36.7, Q1 in m³/h."},{"prompt":"Isothermal efficiency","answer":"42.7/75 = 57.0%","explain":"Isothermal power / actual input."},{"prompt":"Swept volume","answer":"(π/4)×0.25²×0.2×1×2×750 = 14.73 m³/min","explain":"2 single-acting cylinders."},{"prompt":"Volumetric efficiency","answer":"12.57/14.73 = 85.4%","explain":"FAD / swept volume."}],"flash":false,"source":"BEE 2023 P4 N1","order":4046},
{"id":"p4-048","paper":4,"topic":"Refrigeration & AC","kind":"fact","front":"What is 1 TR (ton of refrigeration) in kcal/h, kW and Btu/h?","back":"1 TR = 3024 kcal/h = 3.516 kW = 12,000 Btu/h.","explain":"TR = m × Cp × ΔT (kcal/h) / 3024. With chilled water: TR = flow (m³/h) × 1000 × ΔT / 3024. In kW: kW_r = Q (kg/s) × 4.18 × ΔT, and TR = kW_r / 3.516.","flash":true,"source":"syllabus","order":4047},
{"id":"p4-049","paper":4,"topic":"Refrigeration & AC","kind":"fact","front":"How are kW/TR and COP related?","back":"COP = refrigeration effect / power input = 3.516 / (kW/TR). Example: 0.7 kW/TR ≈ COP 5.0.","explain":"Lower kW/TR (higher COP) is better. Compressor-only kW/TR is often 0.6–0.8 for water-cooled centrifugal or screw chillers. Adding chilled-water pump, condenser pump and cooling-tower fan power gives the overall system kW/TR.","flash":true,"source":"syllabus","order":4048},
{"id":"p4-050","paper":4,"topic":"Refrigeration & AC","kind":"fact","front":"Is kW/TR of an AC plant with an air-cooled condenser lower than one with a water-cooled condenser?","back":"No. An air-cooled condenser has a higher kW/TR, because it condenses near ambient dry-bulb temperature, which is much higher than the wet-bulb temperature a cooling tower can approach.","explain":"Higher condensing temperature means higher lift, which means more compressor work. BEE 2023 T/F: False.","flash":false,"source":"BEE 2023 P4 Q9","order":4049},
{"id":"p4-051","paper":4,"topic":"Refrigeration & AC","kind":"fact","front":"How are the main components of a building cooling load calculated (CLTD/CLF method)?","back":"Conduction = U × A × CLTD; solar through glass = A × SC × SCL; people sensible = n × SHG × CLF (latent without CLF); lighting = W × ballast factor × CLF; infiltration sensible = 1210 × Q × ΔT, latent = 3010 × Q × Δw (Q in m³/s, Δw in g/kg).","explain":"Total load = sum of sensible and latent parts, in W; divide by 3516 for TR. A higher solar cooling load (SCL) factor means a higher AC load (BEE 2024 T/F: 'lower load' is False). Roof insulation lowers U, which cuts the roof conduction term directly.","flash":false,"source":"BEE 2023 P4 N4A","order":4050},
{"id":"p4-052","paper":4,"topic":"Refrigeration & AC","kind":"problem","front":"A water-cooled screw chiller cools 150 m³/h of chilled water from 12 °C to 7 °C. Compressor input is 175 kW. Auxiliaries: chilled water pump 15 kW, condenser water pump 22 kW, cooling tower fan 8 kW. Find TR, chiller kW/TR, COP and system kW/TR.","back":"≈ 248 TR; chiller 0.706 kW/TR; COP ≈ 4.98; system ≈ 0.887 kW/TR","explain":"Auxiliaries add about 25% to the chiller's own specific power here. That is why pump and fan optimisation (VFDs, right-sizing, lower head) is part of every chiller audit. BEE 2025 asked for both 'chiller SEC' and 'overall SEC' in kWh/TR.","steps":[{"prompt":"Refrigeration load","answer":"150 × 1000 × 5/3024 = 248.0 TR","explain":"TR = m Cp ΔT / 3024 (kcal basis)."},{"prompt":"Chiller kW/TR","answer":"175/248.0 = 0.706 kW/TR","explain":"Compressor power / TR."},{"prompt":"COP","answer":"3.516/0.706 = 4.98","explain":"COP = 3.516 / (kW/TR)."},{"prompt":"System kW/TR","answer":"(175 + 15 + 22 + 8)/248.0 = 220/248 = 0.887 kW/TR","explain":"Add pumps and tower fan."}],"flash":false,"source":"BEE 2025 P4 N1","order":4051},
{"id":"p4-053","paper":4,"topic":"Refrigeration & AC","kind":"problem","front":"A steam-fired vapour absorption chiller cools 0.12 m³/s of chilled water from 12 °C to 7 °C (Cp 4.18 kJ/kg K). It uses 1.5 kg/s of steam (enthalpy 2760 kJ/kg) and condensate leaves at 100 °C. Find the refrigeration effect in TR, the heat input and the COP.","back":"≈ 2508 kW = 713 TR; heat input ≈ 3513 kW; COP ≈ 0.71","explain":"Condensate enthalpy ≈ 4.18 × 100 = 418 kJ/kg. A COP near 0.7 is typical of a single-effect VAM. Double-effect machines reach about 1.2–1.4. VAMs make sense where waste heat or cheap low-pressure steam is available.","steps":[{"prompt":"Refrigeration effect","answer":"0.12 × 1000 × 4.18 × 5 = 2508 kW","explain":"m Cp ΔT."},{"prompt":"Convert to TR","answer":"2508/3.516 = 713 TR","explain":"1 TR = 3.516 kW."},{"prompt":"Heat input","answer":"1.5 × (2760 − 418) = 3513 kW","explain":"Steam enthalpy − condensate enthalpy."},{"prompt":"COP","answer":"2508/3513 = 0.71","explain":"Refrigeration effect / heat input."}],"flash":false,"source":"BEE 2023 P4 L1","order":4052},
{"id":"p4-054","paper":4,"topic":"Cooling towers","kind":"fact","front":"Define range, approach and effectiveness of a cooling tower.","back":"Range = hot water in − cold water out; Approach = cold water out − ambient WBT; Effectiveness = Range / (Range + Approach) × 100.","explain":"Range + Approach = hot water temperature − WBT, which is the maximum possible cooling. Approach is the better indicator of tower performance, because range is set by the process heat load. Cold water can never be cooled below WBT.","flash":true,"source":"syllabus","order":4053},
{"id":"p4-055","paper":4,"topic":"Cooling towers","kind":"fact","front":"What is the formula for evaporation loss in a cooling tower?","back":"Evaporation loss (m³/h) = 0.00085 × 1.8 × circulation rate (m³/h) × Range (°C).","explain":"Roughly 1% of circulating water evaporates for every 7 °C of range. Make-up = evaporation + blowdown + drift. Heat rejected (kcal/h) = flow (kg/h) × range.","flash":true,"source":"BEE 2024 P4 N3","order":4054},
{"id":"p4-056","paper":4,"topic":"Cooling towers","kind":"fact","front":"How are cycles of concentration (COC) and blowdown related in a cooling tower?","back":"COC = TDS (or chlorides) of circulating water / TDS of make-up water. Blowdown = Evaporation loss / (COC − 1).","explain":"Raising COC (with better water treatment) cuts blowdown and so make-up water. Going from COC 2 to 4 cuts blowdown from 1.0E to 0.33E. Drift loss is small in towers with good drift eliminators.","flash":false,"source":"syllabus","order":4055},
{"id":"p4-057","paper":4,"topic":"Cooling towers","kind":"problem","front":"A cooling tower circulates 3000 m³/h. Hot water enters at 40 °C and leaves at 32 °C; ambient WBT is 27 °C. TDS is 2000 ppm in circulating water and 500 ppm in make-up. Find range, approach, effectiveness, heat rejected, evaporation loss, blowdown and make-up (ignore drift).","back":"Range 8 °C; approach 5 °C; ε ≈ 61.5%; heat rejected 240 lakh kcal/h (≈ 7937 TR); evaporation ≈ 36.7 m³/h; blowdown ≈ 12.2 m³/h; make-up ≈ 49 m³/h","explain":"BEE 2024 built a sump-level/time problem on these flows, so get the mass balance right: make-up in = evaporation + blowdown out. If effectiveness and approach are given, back-solve range = ε × approach / (1 − ε).","steps":[{"prompt":"Range and approach","answer":"Range = 40 − 32 = 8 °C; Approach = 32 − 27 = 5 °C","explain":"Definitions."},{"prompt":"Effectiveness","answer":"8/(8 + 5) = 61.5%","explain":"Range / (range + approach)."},{"prompt":"Heat rejected","answer":"3000 × 1000 × 8 = 24 × 10⁶ kcal/h ÷ 3024 = 7937 TR","explain":"m × ΔT, water Cp ≈ 1."},{"prompt":"Evaporation loss","answer":"0.00085 × 1.8 × 3000 × 8 = 36.7 m³/h","explain":"BEE evaporation formula."},{"prompt":"Blowdown and make-up","answer":"COC = 2000/500 = 4 → BD = 36.72/3 = 12.24 m³/h; make-up = 48.96 m³/h","explain":"BD = E/(COC − 1); make-up = E + BD."}],"flash":false,"source":"BEE 2024 P4 N3","order":4056},
{"id":"p4-058","paper":4,"topic":"Lighting","kind":"fact","front":"How are Installed Load Efficacy (ILE) and the Installed Load Efficacy Ratio (ILER) assessed?","back":"ILE (lux/W/m²) = average maintained lux / (total input W / floor area). ILER = actual ILE / target ILE. ILER ≥ 0.75: satisfactory to good; 0.51–0.74: review suggested; ≤ 0.5: urgent action required.","explain":"Target ILE depends on room index and application. Input watts must include ballast or driver losses. Room index = (L × W) / [Hm × (L + W)], where Hm is the luminaire mounting height above the work plane.","flash":false,"source":"syllabus","order":4057},
{"id":"p4-059","paper":4,"topic":"DG sets","kind":"fact","front":"What are the key performance indicators of a diesel generator set?","back":"Specific energy generation (kWh/litre) = kWh generated / litres of fuel; thermal efficiency = kWh × 860 / (fuel kg × GCV). Loading % = kW / (kVA × PF rating).","explain":"kWh/litre is the everyday KPI and it falls sharply at low loading. DG sets run most efficiently at about 60–80% load. Exhaust gas (often 400–500 °C) and jacket water are waste-heat recovery opportunities.","flash":false,"source":"syllabus","order":4058},
{"id":"p4-060","paper":4,"topic":"DG sets","kind":"problem","front":"A 500 kVA (0.8 PF) DG set generates 1500 kWh in 5 hours using 420 litres of HSD (density 0.83 kg/l, GCV 10,800 kcal/kg). Find average loading, specific energy generation, thermal efficiency, and generation cost at ₹90/litre.","back":"Load ≈ 75%; ≈ 3.57 kWh/litre; thermal efficiency ≈ 34.3%; ≈ ₹25.2/kWh","explain":"Average kW = 1500/5 = 300 kW against 400 kW rated (500 kVA × 0.8). Fuel cost per kWh is often 2–3 times the grid tariff, so DG output should be kept to essential or backup loads.","steps":[{"prompt":"Average loading","answer":"300 kW / (500 × 0.8) = 75%","explain":"kW / rated kW."},{"prompt":"Specific energy generation","answer":"1500/420 = 3.57 kWh/litre","explain":"kWh ÷ litres."},{"prompt":"Fuel heat input","answer":"420 × 0.83 × 10,800 = 37.65 lakh kcal","explain":"litres × density × GCV."},{"prompt":"Thermal efficiency","answer":"1500 × 860/37.65 lakh = 34.3%","explain":"Output heat-equivalent / input."},{"prompt":"Cost of generation","answer":"90/3.57 = ₹25.2/kWh","explain":"Fuel price ÷ kWh per litre."}],"flash":false,"source":"syllabus","order":4059},
{"id":"p4-061","paper":4,"topic":"Power plant / turbines","kind":"fact","front":"How are heat rate and efficiency related, and how do gross and net heat rate differ?","back":"Efficiency % = 860 / Heat rate (kcal/kWh) × 100. Unit gross HR = turbine HR / boiler efficiency; Net HR = Gross HR / (1 − aux power fraction).","explain":"Example: turbine HR 2045 and boiler efficiency 87.5% give gross HR 2338. With 7% auxiliary consumption, net HR is 2514 kcal/kWh, which is 34.2% efficiency. Under PAT, net heat-rate reduction × generation gives the toe saved.","flash":true,"source":"BEE 2023 P4 N4B","order":4060},
{"id":"p4-062","paper":4,"topic":"Power plant / turbines","kind":"fact","front":"What is the formula for turbine cycle heat rate in a reheat unit?","back":"THR = [M_ms (h_ms − h_fw) + M_rh (h_hrh − h_crh)] / Gross generation (kWh), in kcal/kWh.","explain":"M in kg/h and generation in kW. The first term is heat added in the boiler to main steam, and the second is heat added in the reheater. Boiler efficiency is not part of THR (BEE 2023 T/F: 'boiler efficiency affects turbine HR' is False). It only enters when converting to unit heat rate.","flash":false,"source":"BEE 2023 P4 Q2","order":4061},
{"id":"p4-063","paper":4,"topic":"Power plant / turbines","kind":"fact","front":"Define TTD and DCA of a feed-water heater. Is lower or higher better?","back":"TTD = saturation temperature of extraction steam − feed-water outlet temperature. DCA = drain outlet temperature − feed-water inlet temperature. Lower TTD and DCA mean better heater performance and a better cycle heat rate.","explain":"A higher TTD means the feed water leaves cooler, so the boiler must add more heat. A higher DCA means drains carry heat to the next heater down. BEE gives rules such as 0.014% HR per 0.56 °C TTD deviation and 0.005% per 0.56 °C DCA deviation (BEE 2023 T/F False; BEE 2025 T/F True).","flash":false,"source":"BEE 2025 P4 Q6","order":4062},
{"id":"p4-064","paper":4,"topic":"Power plant / turbines","kind":"fact","front":"How do condenser vacuum and cooling water temperature affect heat rate?","back":"A better vacuum (lower back pressure) and colder cooling water both improve (lower) the heat rate. Vacuum (mmHg) = barometric pressure (≈760 mmHg) − absolute back pressure (mmHg).","explain":"Lower exhaust pressure increases the enthalpy drop across the LP turbine, so more kWh come from the same steam. Fouled condenser tubes, air ingress and poor cooling-tower approach all raise back pressure (BEE 2024: 'increasing vacuum increases HR' is False; BEE 2025: 'colder CW improves HR' is True).","flash":false,"source":"BEE 2024 P4 Q5","order":4063},
{"id":"p4-065","paper":4,"topic":"Cogeneration","kind":"fact","front":"For a 20 MW cogeneration plant, does a back-pressure turbine have a lower steam rate (kg/kWh) than an extraction-condensing turbine?","back":"No. A back-pressure turbine has a higher steam rate, because steam leaves at process pressure with a smaller enthalpy drop per kg.","explain":"Steam rate = steam flow / power = 860/(Δh × η). Extraction-condensing machines expand part of the steam down to vacuum and get more kWh per kg. Back-pressure systems still have the highest overall fuel utilisation when all exhaust heat is used in process. BEE 2024 T/F: False.","flash":false,"source":"BEE 2024 P4 Q8","order":4064},
{"id":"p4-066","paper":4,"topic":"Cogeneration","kind":"fact","front":"Define Energy Utilisation Factor (EUF) and heat-to-power ratio for a cogeneration plant.","back":"EUF = (electrical output + useful thermal output) / fuel energy input. Heat-to-power ratio = useful thermal output (kWth) / electrical output (kWe).","explain":"Express all terms in the same unit (kW or kcal/h; 1 kW = 860 kcal/h). Back-pressure steam turbine plants have high heat-to-power ratios (often 4–10). Gas turbine plus HRSG plants have much lower ratios. Matching the plant's ratio to the site's demand is the key cogeneration selection criterion.","flash":false,"source":"BEE 2024 P4 N2","order":4065},
{"id":"p4-067","paper":4,"topic":"Power plant / turbines","kind":"problem","front":"A reheat unit has main-steam flow 1450 TPH (h = 805 kcal/kg), feed water enthalpy 245 kcal/kg, and reheat flow 1310 TPH (CRH 731, HRH 845 kcal/kg). Gross output is 470 MW, boiler efficiency 87.5%, auxiliary consumption 7%. Find turbine heat rate, unit gross heat rate, net heat rate and net efficiency, and the coal burnt per hour (GCV 4000 kcal/kg).","back":"THR ≈ 2045 kcal/kWh; gross HR ≈ 2338; net HR ≈ 2514 kcal/kWh; net η ≈ 34.2%; coal ≈ 275 t/h","explain":"Keep units consistent: flows in kg/h and power in kW give kcal/kWh directly. Coal burnt = gross HR × gross kWh / GCV, because gross HR already includes boiler losses.","steps":[{"prompt":"Heat added to main steam","answer":"1,450,000 × (805 − 245) = 8120 × 10⁵ kcal/h","explain":"M_ms (h_ms − h_fw)."},{"prompt":"Heat added in reheater","answer":"1,310,000 × (845 − 731) = 1493 × 10⁵ kcal/h","explain":"M_rh (h_hrh − h_crh)."},{"prompt":"Turbine heat rate","answer":"(8120 + 1493.4) × 10⁵ / 470,000 = 2045 kcal/kWh","explain":"Total heat / kWh."},{"prompt":"Gross and net heat rate","answer":"Gross = 2045/0.875 = 2338; Net = 2338/0.93 = 2514 kcal/kWh","explain":"Divide by boiler efficiency, then by (1 − aux)."},{"prompt":"Net efficiency and coal","answer":"η = 860/2514 = 34.2%; coal = 2338 × 470,000/4000 = 274.7 t/h","explain":"Efficiency = 860/HR."}],"flash":false,"source":"BEE 2023 P4 N4B","order":4066},
{"id":"p4-068","paper":4,"topic":"Cogeneration","kind":"problem","front":"A back-pressure cogeneration plant takes 60 TPH of steam to the turbine at 820 kcal/kg. Steam exhausts at 680 kcal/kg (actual) to process, and condensate returns at 100 °C. Gearbox × alternator efficiency is 95%. The boiler makes this steam at 825 kcal/kg from 105 °C feed water at 70% efficiency, firing bagasse (GCV 2270 kcal/kg). Find power, steam rate, heat-to-power ratio, bagasse consumption and EUF.","back":"Power ≈ 9279 kW; steam rate ≈ 6.47 kg/kWh; H/P ≈ 4.36; bagasse ≈ 27.2 TPH; EUF ≈ 69%","explain":"This mirrors the BEE 2024 sugar cogeneration question. Raising inlet steam pressure and temperature increases Δh, which gives more power from the same process steam. That is why high-pressure boiler upgrades raise power export.","steps":[{"prompt":"Power output","answer":"60,000 × (820 − 680)/860 × 0.95 = 9279 kW","explain":"m Δh / 860 × η(gearbox × alternator)."},{"prompt":"Steam rate","answer":"60,000/9279 = 6.47 kg/kWh","explain":"Steam flow / power."},{"prompt":"Useful process heat","answer":"60,000 × (680 − 100)/860 = 40,465 kWth","explain":"Heat given up to process."},{"prompt":"Heat-to-power ratio","answer":"40,465/9279 = 4.36","explain":"kWth / kWe."},{"prompt":"Bagasse use and EUF","answer":"Bagasse = 60,000×(825 − 105)/(0.70×2270) = 27,187 kg/h → input 71,761 kW; EUF = (9279 + 40,465)/71,761 = 69.3%","explain":"Fuel = steam heat / (η × GCV); EUF = useful out / fuel in."}],"flash":false,"source":"BEE 2024 P4 N2","order":4067},
{"id":"p4-069","paper":4,"topic":"Cogeneration","kind":"problem","front":"A gas turbine burns 1200 Sm³/h of natural gas (LHV 8500 kcal/Sm³) and generates 3.0 kWh/Sm³. Exhaust of 14 kg/s enters the HRSG at 515 °C and leaves at 150 °C (Cp 0.26 kcal/kg°C, HRSG efficiency 80%). Steam enthalpy is 663 kcal/kg and feed water is at 105 °C. Find power, steam generation and EUF, and the extra steam if HRSG exit is lowered to 110 °C.","back":"Power 3600 kW; steam ≈ 6.86 TPH; EUF ≈ 67.9%; at 110 °C exit steam ≈ 7.61 TPH (+0.75 TPH), EUF ≈ 72%","explain":"Heat picked up in the HRSG = m × Cp × (T_in − T_out) × η_HRSG. Lowering the exit temperature is limited by the acid dew point for sulphur-bearing fuels, but natural gas allows quite low stack temperatures.","steps":[{"prompt":"Power output","answer":"1200 × 3.0 = 3600 kW","explain":"Fuel rate × specific generation."},{"prompt":"Heat recovered in HRSG","answer":"14 × 3600 × 0.26 × (515 − 150) × 0.8 = 38.26 lakh kcal/h","explain":"m Cp ΔT × η_HRSG."},{"prompt":"Steam generated","answer":"38.26 lakh/(663 − 105) = 6857 kg/h","explain":"Heat / (h_s − h_fw)."},{"prompt":"EUF","answer":"Fuel = 1200×8500/860 = 11,860 kW; steam heat = 4449 kW; EUF = (3600 + 4449)/11,860 = 67.9%","explain":"All in kW."},{"prompt":"Lower exit temperature (110 °C)","answer":"Heat = 42.46 lakh kcal/h → 7609 kg/h (+752 kg/h); EUF = (3600 + 4937)/11,860 = 72.0%","explain":"Repeat with ΔT = 405 °C."}],"flash":false,"source":"BEE 2025 P4 N3(i)","order":4068},
{"id":"p4-070","paper":4,"topic":"Renewable energy","kind":"fact","front":"What is the formula for wind turbine power, and what is the Betz limit?","back":"P = ½ × ρ × A × V³ × Cp (× drive-train efficiency). Betz limit: Cp,max = 16/27 ≈ 59.3%.","explain":"Power varies with the cube of wind speed, so a 10% higher wind speed gives about 33% more power, and with the square of rotor diameter. Air density ≈ 1.225 kg/m³ at sea level. Practical rotors reach Cp of about 0.40–0.48.","flash":true,"source":"syllabus","order":4069},
{"id":"p4-071","paper":4,"topic":"Renewable energy","kind":"fact","front":"How is the annual energy yield of a solar PV plant estimated?","back":"Energy (kWh/yr) = kWp × peak sun hours (kWh/m²/day) × performance ratio × 365. CUF = annual kWh / (kWp × 8760).","explain":"Peak sun hours equal daily insolation in kWh/m², because 1 kW/m² is standard test irradiance. The performance ratio (often 0.75–0.80) covers temperature, inverter, cable, soiling and mismatch losses. Indian fixed-tilt plants typically show a CUF of about 16–20%.","flash":false,"source":"syllabus","order":4070},
{"id":"p4-072","paper":4,"topic":"Renewable energy","kind":"problem","front":"A 500 kWp rooftop solar PV plant gets an average of 5.2 kWh/m²/day of irradiation, with a performance ratio of 0.78. Find daily and annual generation and CUF. If grid power costs ₹8/kWh and the plant costs ₹3.5 crore, find the simple payback.","back":"≈ 2028 kWh/day; ≈ 7.40 lakh kWh/yr; CUF ≈ 16.9%; savings ≈ ₹59.2 lakh/yr; payback ≈ 5.9 years","explain":"This is a simplified estimate: real yield also depends on tilt, orientation, shading and degradation (about 0.5–0.7% per year). CUF is a quick check: a value much above 20% for fixed-tilt PV in India should be questioned.","steps":[{"prompt":"Daily generation","answer":"500 × 5.2 × 0.78 = 2028 kWh/day","explain":"kWp × PSH × PR."},{"prompt":"Annual generation","answer":"2028 × 365 = 7,40,220 kWh","explain":"× 365 days."},{"prompt":"CUF","answer":"7,40,220/(500 × 8760) = 16.9%","explain":"Actual / maximum possible."},{"prompt":"Savings and payback","answer":"7,40,220 × 8 = ₹59.2 lakh/yr; payback = 350/59.2 = 5.9 years","explain":"Simple payback = investment / annual savings."}],"flash":false,"source":"syllabus","order":4071},
{"id":"p4-073","paper":4,"topic":"Renewable energy","kind":"problem","front":"A wind turbine has an 80 m rotor diameter. At a wind speed of 8 m/s (air density 1.225 kg/m³), its power coefficient is 0.40 and drive-train × generator efficiency is 0.90. Find the power in the wind, the electrical output, and the output if wind speed rises by 10%.","back":"Wind power ≈ 1576 kW; electrical ≈ 567 kW; at 8.8 m/s ≈ 755 kW","explain":"The cube law dominates: 1.1³ = 1.331, so a 10% higher wind gives 33% more output. This is why hub height and site selection matter so much. Cp × η = 0.36 here, well below the 0.593 Betz limit.","steps":[{"prompt":"Swept area","answer":"π × 80²/4 = 5027 m²","explain":"A = πD²/4."},{"prompt":"Power in the wind","answer":"0.5 × 1.225 × 5027 × 8³ = 1576 kW","explain":"½ρAV³."},{"prompt":"Electrical output","answer":"1576 × 0.40 × 0.90 = 567 kW","explain":"× Cp × η."},{"prompt":"Effect of +10% wind speed","answer":"567 × 1.1³ = 755 kW","explain":"Power ∝ V³."}],"flash":false,"source":"syllabus","order":4072},
{"id":"p4-074","paper":4,"topic":"Textile processing","kind":"fact","front":"How is the drying heat load of a stenter calculated?","back":"Bone-dry cloth = output × (1 − outlet moisture); wet inlet = bone-dry/(1 − inlet moisture); water evaporated = inlet − outlet; heat = evaporated × [(T_out − T_in) + 540] kcal/h. Stenter efficiency = this heat / heat supplied.","explain":"Moisture percentages are on a wet basis, so always go through the bone-dry weight. 540 kcal/kg is the latent heat used in BEE solutions. The heat supplied traces back through the thermic-fluid heater or boiler efficiency to fuel.","flash":false,"source":"BEE 2024 P4 N4B","order":4073},
{"id":"p4-075","paper":4,"topic":"Textile processing","kind":"problem","front":"A stenter delivers 1200 kg/h of cloth at 5% moisture. Cloth enters at 60% moisture (wet basis) and is heated from 30 °C to 85 °C. Stenter efficiency is 50%. Heat comes from a thermic fluid heater (75% efficient) firing furnace oil (GCV 10,000 kcal/kg, density 0.92 kg/l). Find water evaporated, heat load and oil consumption in litres/h.","back":"Evaporation ≈ 1650 kg/h; heat load ≈ 9.82 lakh kcal/h; oil ≈ 262 kg/h ≈ 285 litres/h","explain":"Efficiency improvements multiply through: better stenter efficiency (more chambers, exhaust humidity control) and better heater efficiency both cut oil. Mechanical dewatering (padding/squeezing) before the stenter is the cheapest saving, because each kg of water removed mechanically saves about 600 kcal of thermal energy.","steps":[{"prompt":"Bone-dry cloth","answer":"1200 × 0.95 = 1140 kg/h","explain":"Outlet × (1 − moisture)."},{"prompt":"Wet inlet and water evaporated","answer":"Inlet = 1140/0.40 = 2850 kg/h; evaporated = 2850 − 1200 = 1650 kg/h","explain":"Wet-basis moisture."},{"prompt":"Drying heat load","answer":"1650 × [(85 − 30) + 540] = 9,81,750 kcal/h","explain":"Sensible + latent."},{"prompt":"Heat into stenter and heater","answer":"9,81,750/0.50 = 19,63,500; /0.75 = 26,18,000 kcal/h","explain":"Divide by each efficiency in series."},{"prompt":"Oil consumption","answer":"26,18,000/10,000 = 261.8 kg/h ÷ 0.92 = 284.6 l/h","explain":"kg = heat/GCV; litres = kg/density."}],"flash":false,"source":"BEE 2025 P4 N4D","order":4074},
{"id":"p4-076","paper":4,"topic":"Cement","kind":"fact","front":"What is the formula for the heat of formation of cement clinker (loss-free basis)?","back":"ΔH (kcal/kg clinker) = 2.22 Al₂O₃ + 6.48 MgO + 7.646 CaO − 5.116 SiO₂ − 0.59 Fe₂O₃ (oxides in %).","explain":"Typical ordinary clinker gives about 380–420 kcal/kg. This theoretical heat is the 'useful output' in a kiln heat balance. The real specific thermal energy consumption (often 700–800 kcal/kg in modern plants) is compared against it. Asked in both BEE 2023 and BEE 2024.","flash":false,"source":"BEE 2024 P4 N4C","order":4075},
{"id":"p4-077","paper":4,"topic":"Cement","kind":"fact","front":"In a cement rotary kiln, is the largest heat loss through hot clinker discharge?","back":"No. The largest losses are with the preheater exhaust gases and cooler vent air. Sensible heat in discharged clinker is comparatively small.","explain":"That is why waste-heat recovery boilers are fitted on preheater (PH) and air-quenching cooler (AQC) exhausts for power generation. BEE 2025 T/F: False.","flash":false,"source":"BEE 2025 P4 Q10","order":4076},
{"id":"p4-078","paper":4,"topic":"Steam systems","kind":"fact","front":"Is reducing make-up water the only reason to install a condensate recovery system?","back":"No. Condensate recovery also saves fuel (hot feed water), water-treatment chemicals and blowdown, and it improves feed-water quality.","explain":"Each 6 °C rise in feed-water temperature saves about 1% fuel, and condensate is often returned at 80–100 °C. Lower feed TDS means less blowdown and its heat loss. BEE 2025 T/F: False.","flash":false,"source":"BEE 2025 P4 Q8","order":4077},
{"id":"p4-079","paper":4,"topic":"PAT / benchmarking","kind":"fact","front":"How are energy savings converted to ESCerts under PAT for a thermal power plant?","back":"ESCerts = (baseline net HR − assessment net HR) (kcal/kWh) × baseline generation (kWh) / 10⁷, since 1 ESCert = 1 toe = 10⁷ kcal.","explain":"Example from BEE 2025: gross HR 2300 with 9% aux → net 2527.5. Against a baseline of 2600, the saving is 72.5 kcal/kWh. On 5000 MU that is about 36,264 ESCerts. Always convert gross HR to net HR first.","flash":false,"source":"BEE 2025 P4 L2","order":4078},
{"id":"p4-080","paper":4,"topic":"Waste minimisation","kind":"fact","front":"What are the main waste minimisation techniques?","back":"Source reduction (good housekeeping, input-material change, better process control, equipment modification, technology change), recycling (on-site recovery and reuse, useful by-products), and product modification.","explain":"Source reduction is preferred because it avoids the waste being generated at all. Recycling recovers value from waste already made. Each technique also cuts the energy embedded in the lost material.","flash":false,"source":"syllabus","order":4079}
]$cards$::jsonb);
